<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/cepfms_operational_helpers.php';requireCefPermission('cepfms.proposals.view');
$rows=db()->query("SELECT s.reference_number,s.title,s.created_at,s.priority_level,s.status,c.name category_name,p.estimated_scope,p.feasibility_status,p.disposition,(SELECT COUNT(*) FROM cef_legislative_referrals r WHERE r.submission_id=s.id) referrals FROM cef_submissions s JOIN cef_proposals p ON p.submission_id=s.id LEFT JOIN cef_categories c ON c.id=s.category_id WHERE s.submission_type='Proposal' AND s.deleted_at IS NULL ORDER BY s.created_at DESC")->fetchAll();
$pageTitle='Proposal & Suggestion Report';$activeMenu='proposals';$extraCss=[appUrl('assets/css/cepfms-operational.css')];include __DIR__.'/../../layouts/header.php';
?>
<div class="app-wrapper"><?php include __DIR__.'/../../layouts/sidebar.php'; ?><main class="main-content"><div class="cef-head"><div><div class="cef-eyebrow">Operational Report</div><h1>Proposal & Suggestion Report</h1><p>Citizen proposals by category, scope, feasibility, disposition, legislative referral and status.</p></div><a class="btn btn-outline-secondary" href="index.php">Proposal Registry</a></div><div class="card cef-card"><div class="table-responsive"><table class="table cef-table mb-0"><thead><tr><th>Reference</th><th>Proposal</th><th>Category</th><th>Scope</th><th>Feasibility</th><th>Disposition</th><th>Referrals</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['reference_number']) ?></td><td><?= e($r['title']) ?><div class="small text-muted"><?= formatDateTime($r['created_at']) ?></div></td><td><?= e($r['category_name']?:'Unclassified') ?></td><td><?= e($r['estimated_scope']?:'—') ?></td><td><?= e($r['feasibility_status']) ?></td><td><?= e($r['disposition']?:'—') ?></td><td><?= (int)$r['referrals'] ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></main></div>
<?php include __DIR__.'/../../layouts/footer.php'; ?>
